-- SV migracion sv_2026_09_18_48_world.sql
-- Correctiva del lote de dificultad: el `LootID` de las filas nuevas apuntaba a listas que no
-- tenemos (242.787 avisos) y los disparadores traian dificultades que el cliente no conoce.
-- Idempotente.
--
-- A. LootID heredado/limpiado: 242969 filas con lista inexistente
-- B. PickPocketLootID -> 0: 1601 filas
-- B. SkinLootID -> 0: 4736 filas
-- C. disparadores con dificultad invalida corregidos: 4151

UPDATE `creature_template_difficulty` d
                        JOIN (SELECT Entry, MAX(LootID) L FROM `creature_template_difficulty`
                               WHERE LootID > 0 AND LootID IN (SELECT Entry FROM creature_loot_template)
                               GROUP BY Entry) v ON v.Entry = d.Entry
                           SET d.LootID = v.L
                         WHERE d.LootID > 0 AND d.LootID NOT IN (SELECT Entry FROM creature_loot_template);
UPDATE `creature_template_difficulty`
                         SET `LootID` = 0
                       WHERE `LootID` > 0 AND `LootID` NOT IN (SELECT Entry FROM creature_loot_template);
UPDATE `creature_template_difficulty` SET `PickPocketLootID` = 0 WHERE `PickPocketLootID` > 0 AND `PickPocketLootID` NOT IN (SELECT Entry FROM pickpocketing_loot_template);
UPDATE `creature_template_difficulty` SET `SkinLootID` = 0 WHERE `SkinLootID` > 0 AND `SkinLootID` NOT IN (SELECT Entry FROM skinning_loot_template);
